import java.util.*;
import java.io.*;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int[] a = new int[tokenizer.countTokens()];
        for (int i = 0; i < a.length; i++) {
            a[i] = Integer.parseInt(tokenizer.nextToken());
        }

        tokenizer = new StringTokenizer(reader.readLine());
        int[] b = new int[tokenizer.countTokens()];
        for (int i = 0; i < b.length; i++) {
            b[i] = Integer.parseInt(tokenizer.nextToken());
        }

        tokenizer = new StringTokenizer(reader.readLine());
        int[] c = new int[tokenizer.countTokens()];
        for (int i = 0; i < c.length; i++) {
            c[i] = Integer.parseInt(tokenizer.nextToken());
        }

        int count = 0;
        for (int i = 1; i <= 100000; i++) {
            a[0] = i;
            b[1] = sum(a) - sum(b);
            if (b[1] > 0) {
                if (sum(a) == sum(b)) {
                    c[2] = sum(a) - (b[1] + a[0]);
                    if (c[2] > 0) {
                        if (sum(c) == sum(a) && sum(a) == sum(b) &&
                            (c[0] + b[0] + a[0]) == (c[1] + b[1] + a[1]) &&
                            (c[1] + b[1] + a[1]) == (c[1] + b[1] + a[1])) {
                            count = 1;
                            break;
                        } else {
                            a[0] = 0;
                            b[1] = 0;
                            c[2] = 0;
                        }
                    } else {
                        a[0] = 0;
                        b[1] = 0;
                        c[2] = 0;
                    }
                } else {
                    a[0] = 0;
                    b[1] = 0;
                    c[2] = 0;
                }
            } else {
                a[0] = 0;
                b[1] = 0;
                c[2] = 0;
            }
        }

        printArray(a);
        printArray(b);
        printArray(c);
    }

    private static int sum(int[] array) {
        int total = 0;
        for (int num : array) {
            total += num;
        }
        return total;
    }

    private static void printArray(int[] array) {
        StringBuilder sb = new StringBuilder();
        for (int num : array) {
            sb.append(num).append(" ");
        }
        System.out.println(sb.toString().trim());
    }
}

